<?php
namespace App\Services\DevOps;use App\Models\{ZigoDeployment,ZigoDevOpsAlert};
final class DevOpsAlertService {public function create(string $type,string $severity,string $title,string $message,?string $environment=null,?ZigoDeployment $deployment=null,array $metadata=[]):ZigoDevOpsAlert{return ZigoDevOpsAlert::create(['type'=>$type,'severity'=>$severity,'environment'=>$environment??$deployment?->environment,'deployment_id'=>$deployment?->id,'title'=>mb_substr(strip_tags($title),0,255),'message'=>mb_substr(strip_tags($message),0,4000),'status'=>'open','metadata'=>$metadata]);}public function acknowledge(ZigoDevOpsAlert $alert,int $userId):ZigoDevOpsAlert{$alert->update(['status'=>'acknowledged','acknowledged_by_user_id'=>$userId,'acknowledged_at'=>now()]);return$alert->refresh();}}
